nonisolated struct AgentKernelRunOptions: @unchecked Sendable {
    nonisolated enum GroundingMode: Sendable, Equatable {
        case foregroundChat
        case headlessTrigger
        case slotAgent
        case rolePipeline
    }

    let modelContext: ModelContext?
    let conversationID: UUID?
    let turnID: UUID?
    let groundingMode: GroundingMode
    let allowDegradedGrounding: Bool
    let preventDoubleGrounding: Bool
    let diagnosticsEnabled: Bool

    static var `default`: AgentKernelRunOptions {
        .init(
            modelContext: nil,
            conversationID: nil,
            turnID: nil,
            groundingMode: .foregroundChat,
            allowDegradedGrounding: true,
            preventDoubleGrounding: true,
            diagnosticsEnabled: false
        )
    }
}

extension AgentKernelRunOptions {
    init(_ legacy: LegacyAgentRunOptions) {
        self.init(
            modelContext: legacy.modelContext,
            conversationID: legacy.conversationID,
            turnID: legacy.turnID,
            groundingMode: .init(legacy.groundingMode),
